grader.code:
// Parses the formulas and recounts every element; it doesn't just compare with the stored solution.
function parse(f) {
  let i = 0;
  const s = String(f).replace(/\s+/g, "");
  const num = () => {
    let n = "";
    while (i < s.length && /\d/.test(s[i])) n += s[i++];
    return n ? Number(n) : 1;
  };
  function group() {
    const out = {};
    while (i < s.length && s[i] !== ")") {
      let part;
      if (s[i] === "(") { i++; part = group(); i++; }
      else {
        const m = /^[A-Z][a-z]?/.exec(s.slice(i));
        if (!m) throw new Error("can't read " + f);
        i += m[0].length;
        part = { [m[0]]: 1 };
      }
      const k = num();
      for (const [e, c] of Object.entries(part)) out[e] = (out[e] ?? 0) + c * k;
    }
    return out;
  }
  return group();
}
const species = [...view.reactants, ...view.products];
const atoms = species.map(parse);
const nl = view.reactants.length;
const elements = [];
for (const a of atoms) for (const e of Object.keys(a)) if (!elements.includes(e)) elements.push(e);

const c = Array.isArray(answer) ? answer.map(Number) : [];
if (c.length !== species.length || !c.every((x) => Number.isInteger(x) && x >= 1))
  return { score: 0, feedback: "Every species needs a whole-number coefficient of at least 1.", details: { tally: [] } };

const tally = elements.map((e) => {
  let left = 0, right = 0;
  atoms.forEach((a, k) => (k < nl ? (left += (a[e] ?? 0) * c[k]) : (right += (a[e] ?? 0) * c[k])));
  return { element: e, left, right };
});
const off = tally.filter((t) => t.left !== t.right);
const gcd = (a, b) => (b ? gcd(b, a % b) : a);
const g = c.reduce((a, b) => gcd(a, b));
if (off.length) {
  return {
    score: 0,
    feedback: `Not balanced: ${off.map((t) => `${t.element} is ${t.left} on the left, ${t.right} on the right`).join("; ")}.`,
    details: { tally, balanced: false },
  };
}
if (g > 1) {
  return {
    score: 0.75,
    feedback: `Balanced, but every coefficient divides by ${g}. The convention is the smallest whole numbers: ${c.map((x) => x / g).join(", ")}.`,
    details: { tally, balanced: true, reduced: false, divisor: g },
  };
}
return { score: 1, details: { tally, balanced: true, reduced: true } };

types.prepare:
// Parses every formula into atom counts (public: the species are the question) and solves the
// balanced coefficients exactly, by Gaussian elimination over fractions. The solution stays in the key.
function parse(f) {
  let i = 0;
  const s = String(f).replace(/\s+/g, "");
  const num = () => {
    let n = "";
    while (i < s.length && /\d/.test(s[i])) n += s[i++];
    return n ? Number(n) : 1;
  };
  function group() {
    const out = {};
    while (i < s.length && s[i] !== ")") {
      let part;
      if (s[i] === "(") {
        i++;
        part = group();
        if (s[i] !== ")") throw new Error("unclosed ( in " + f);
        i++;
      } else {
        const m = /^[A-Z][a-z]?/.exec(s.slice(i));
        if (!m) throw new Error("can't read " + f + " at " + s.slice(i));
        i += m[0].length;
        part = { [m[0]]: 1 };
      }
      const k = num();
      for (const [e, c] of Object.entries(part)) out[e] = (out[e] ?? 0) + c * k;
    }
    return out;
  }
  const r = group();
  if (i < s.length) throw new Error("stray ) in " + f);
  return r;
}

const species = [...fields.reactants, ...fields.products];
const atoms = species.map(parse);
const nl = fields.reactants.length;
const elements = [];
for (const c of atoms) for (const e of Object.keys(c)) if (!elements.includes(e)) elements.push(e);

// Fractions as [num, den] with small integers.
const gcd = (a, b) => (b ? gcd(b, a % b) : Math.abs(a));
const fr = (n, d = 1) => { const g = gcd(n, d) || 1; return d < 0 ? [-n / g, -d / g] : [n / g, d / g]; };
const sub = (a, b) => fr(a[0] * b[1] - b[0] * a[1], a[1] * b[1]);
const mul = (a, b) => fr(a[0] * b[0], a[1] * b[1]);
const div = (a, b) => fr(a[0] * b[1], a[1] * b[0]);

// Rows: elements. Columns: species, products negated. Solve M c = 0.
const n = species.length;
const M = elements.map((e) => atoms.map((c, k) => fr((c[e] ?? 0) * (k < nl ? 1 : -1))));
const pivots = [];
let row = 0;
for (let col = 0; col < n && row < M.length; col++) {
  const p = M.findIndex((r, i) => i >= row && r[col][0] !== 0);
  if (p < 0) continue;
  [M[row], M[p]] = [M[p], M[row]];
  const pv = M[row][col];
  M[row] = M[row].map((x) => div(x, pv));
  for (let i = 0; i < M.length; i++) {
    if (i === row || M[i][col][0] === 0) continue;
    const f = M[i][col];
    M[i] = M[i].map((x, j) => sub(x, mul(f, M[row][j])));
  }
  pivots.push(col);
  row++;
}
let solution = null;
const free = [...Array(n).keys()].filter((c) => !pivots.includes(c));
if (free.length === 1) {
  const fc = free[0];
  const c = new Array(n).fill(null);
  c[fc] = fr(1);
  pivots.forEach((pc, r) => (c[pc] = fr(-M[r][fc][0], M[r][fc][1])));
  const lcm = c.reduce((l, x) => (l * x[1]) / gcd(l, x[1]), 1);
  let ints = c.map((x) => (x[0] * lcm) / x[1]);
  const g = ints.reduce((a, b) => gcd(a, b));
  ints = ints.map((x) => x / g);
  if (ints.every((x) => x < 0)) ints = ints.map((x) => -x);
  if (ints.every((x) => x > 0)) solution = ints;
}
if (!solution) throw new Error("this equation has no single balanced form; check the formulas");

const max = Math.max(Math.max(...solution), Math.min(30, Number(fields.max) || 12));
return {
  view: {
    prompt: fields.prompt ?? "",
    reactants: fields.reactants,
    products: fields.products,
    atoms,
    elements,
    max,
  },
  key: { solution, explanation: fields.explanation ?? "" },
};

template.css:
.sc-eyebrow { font-size: 0.72rem; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: var(--highlight); margin-bottom: -0.5rem; }
.sc-how { font-size: 0.85rem; color: var(--muted-foreground); border-top: 1px solid var(--border); padding-top: 0.75rem; margin: 0.25rem 0 0; }

/* The equation. Each side stays on one line; a narrow card breaks the line at the arrow. */
.bl-eq { display: flex; flex-wrap: wrap; justify-content: center; align-items: center; gap: 0.6rem 0; padding: 0.75rem 0 0.25rem; font-size: 1.45rem; }
.bl-side { display: inline-flex; align-items: center; white-space: nowrap; }
.bl-plus, .bl-arrow { color: var(--muted-foreground); padding: 0 0.45em; font-size: 0.95em; }
.bl-arrow { padding: 0 0.55em; }
.bl-term { display: inline-flex; align-items: center; gap: 0.1em; }
.bl-formula { cursor: text; line-height: 1; }
.bl-formula .katex { font-size: 1.12em; }

/* Coefficient: the number, with a small chevron above and below it. */
.bl-coef-box { position: relative; display: inline-flex; flex-direction: column; align-items: center; }
.bl-coef {
  width: 1.1em; min-width: 1.1em; padding: 0.06em 0.08em; margin: 0;
  font: 400 1em/1.1 KaTeX_Main, "Times New Roman", serif; font-variant-numeric: tabular-nums;
  text-align: center; color: var(--highlight); caret-color: var(--highlight);
  background: color-mix(in oklab, var(--foreground) 5%, transparent); border: none; border-radius: 0.3rem; outline: none;
  transition: background 0.15s, color 0.15s;
}
.bl-coef:focus { background: color-mix(in oklab, var(--highlight) 14%, transparent); }
.bl-coef:disabled { opacity: 1; -webkit-text-fill-color: currentColor; }
.bl-term.is-one .bl-coef { color: var(--muted-foreground); }
.bl-term.is-one .bl-coef:focus { color: var(--highlight); }
.bl-step {
  display: flex; align-items: center; justify-content: center;
  width: 2.5rem; height: 1.75rem; margin: 0 -0.7rem; padding: 0;
  border: none; border-radius: 0.4rem; background: transparent; color: var(--muted-foreground);
  cursor: pointer; touch-action: manipulation; -webkit-tap-highlight-color: transparent;
  opacity: 0.55; transition: opacity 0.15s, background 0.15s, color 0.15s;
}
.bl-step svg { width: 0.85rem; height: 0.55rem; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.bl-term:hover .bl-step, .bl-term:focus-within .bl-step { opacity: 1; }
.bl-step:hover:not(:disabled) { background: var(--accent); color: var(--foreground); }
.bl-step:active:not(:disabled) { color: var(--highlight); }
.bl-step:disabled { opacity: 0.22 !important; cursor: default; }
@media (hover: none) { .bl-step { opacity: 0.85; } }
[data-mode="result"] .bl-step { visibility: hidden; height: 0.5rem; }
[data-mode="result"] .bl-formula { cursor: default; }

/* After grading: the learner's coefficients keep their place, colored by the verdict. */
.bl-eq.right .bl-coef, .bl-eq.right .bl-term.is-one .bl-coef { color: var(--success); }
.bl-eq.near .bl-coef, .bl-eq.near .bl-term.is-one .bl-coef { color: var(--warning); }
.bl-eq.wrong .bl-coef { color: var(--foreground); }
.bl-eq.wrong .bl-term.off .bl-coef { color: var(--danger); text-decoration: underline wavy color-mix(in oklab, var(--danger) 75%, transparent); text-decoration-thickness: 1px; text-underline-offset: 0.18em; }

/* The atom ledger, ruled like a table in a paper: a rule on top, one under the head, one at the end.
   Columns: atom | left bar | left count | relation | right count | right bar | check. */
.bl-ledger { width: 100%; max-width: 30rem; margin: 0 auto; border-top: 1.5px solid color-mix(in oklab, var(--foreground) 55%, transparent); border-bottom: 1.5px solid color-mix(in oklab, var(--foreground) 55%, transparent); font-variant-numeric: tabular-nums; }
.bl-row { display: grid; grid-template-columns: 2.5rem 1fr 2.2rem 1.6rem 2.2rem 1fr 2.5rem; align-items: center; min-height: 2.6rem; padding: 0 0.25rem; }
.bl-row + .bl-row:not(.bl-head) { border-top: 1px solid color-mix(in oklab, var(--border) 70%, transparent); }
.bl-row > .el { font-size: 1.12rem; padding-left: 0.25rem; }
.bl-row .n { font: 1.15rem/1 KaTeX_Main, "Times New Roman", serif; transition: color 0.2s; }
.bl-row .n.l { text-align: right; }
.bl-row .n.r { text-align: left; }
.bl-row .rel { text-align: center; font: 1.05rem/1 KaTeX_Main, "Times New Roman", serif; color: var(--muted-foreground); }
.bl-row .track { display: flex; align-items: center; height: 1.3rem; }
.bl-row .track.l { justify-content: flex-end; padding-right: 0.55rem; }
.bl-row .track.r { justify-content: flex-start; padding-left: 0.55rem; }
.bl-row .bar { display: block; height: 0.36rem; width: 0; border-radius: 999px; background: color-mix(in oklab, var(--foreground) 55%, transparent); transition: width 0.35s cubic-bezier(0.22, 1, 0.36, 1), background 0.2s; }
.bl-head { min-height: 2.1rem; border-bottom: 1px solid color-mix(in oklab, var(--foreground) 30%, transparent); font-size: 0.75rem; color: var(--muted-foreground); white-space: nowrap; }
.bl-head > .el { font-size: 0.75rem; padding-left: 0.25rem; }
.bl-head .hl { grid-column: 2 / 4; text-align: right; }
.bl-head .hr { grid-column: 5 / 7; text-align: left; }
.bl-head .rel { grid-column: 4; font: inherit; color: inherit; }
/* An unbalanced row: the relation carries the accent; the bars show by how much. */
.bl-row.more-l .rel, .bl-row.more-r .rel { color: var(--highlight); font-weight: 700; }
.bl-row .st .d { font: 0.78rem var(--font-sans); color: var(--muted-foreground); white-space: nowrap; }
.bl-row.ok .bar { background: color-mix(in oklab, var(--success) 65%, transparent); }
.bl-row.ok .n, .bl-row.ok .rel { color: color-mix(in oklab, var(--success) 82%, var(--foreground)); }
.bl-row .st { display: flex; justify-content: center; color: color-mix(in oklab, var(--success) 82%, var(--foreground)); }
.bl-row .st svg { width: 1rem; height: 1rem; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.bl-sum { padding: 0.5rem 0.25rem; border-top: 1px solid color-mix(in oklab, var(--foreground) 30%, transparent); font-size: 0.8rem; color: var(--muted-foreground); text-align: center; }
.bl-ledger.all-ok .bl-sum { color: color-mix(in oklab, var(--success) 82%, var(--foreground)); font-weight: 500; }

.bl-hint { font-size: 0.82rem; text-align: center; margin: -0.25rem 0 0; }
@media (pointer: coarse) { .bl-hint .kb { display: none; } }

/* The balanced equation in the reveal. */
.bl-final { display: flex; flex-wrap: wrap; justify-content: center; align-items: baseline; gap: 0.4rem 0; padding: 0.4rem 0; font-size: 1.3rem; }
.bl-final .s { display: inline-flex; align-items: baseline; white-space: nowrap; }
.bl-final .t { display: inline-flex; align-items: baseline; gap: 0.3em; }
.bl-final .c { font-family: KaTeX_Main, "Times New Roman", serif; font-size: 1.12em; }
.bl-final .c.hit { color: var(--highlight); text-decoration: underline; text-decoration-thickness: 1.5px; text-underline-offset: 0.2em; }
.bl-final .op { color: var(--muted-foreground); padding: 0 0.45em; }
.bl-final .katex { font-size: 1.12em; }
.bl-note { margin: 0; font-size: 0.85rem; color: var(--muted-foreground); text-align: center; }

@media (max-width: 480px) {
  .bl-eq { font-size: 1.25rem; }
  .bl-row { grid-template-columns: 2.1rem 1fr 1.9rem 1.3rem 1.9rem 1fr 1.8rem; }
  .bl-final { font-size: 1.1rem; }
}
[data-mode="result"] .bl-coef { background-color: transparent; }
.bl-note.ok { display: flex; align-items: center; justify-content: center; gap: 0.4rem; color: var(--success); font-weight: 500; font-size: 0.9rem; }
.bl-note.ok svg { width: 1rem; height: 1rem; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.bl-ledger.near .bl-sum { color: color-mix(in oklab, var(--warning) 70%, var(--foreground)); }
[data-mode="result"] .bl-ledger { margin-bottom: 0.25rem; }

template.js:
const { view } = etude;
const nl = view.reactants.length;
const species = [...view.reactants, ...view.products];
const max = view.max;
// Digits after an element or a closing bracket are subscripts: Al2(SO4)3 → \mathrm{Al_2(SO_4)_3}.
const formulaTex = (f) => "\\mathrm{" + String(f).replace(/([A-Za-z)])(\d+)/g, "$1_{$2}") + "}";
const tex = (s) => etude.mdInline("$" + s + "$");
const chevron = (d) => `<svg viewBox="0 0 16 10" aria-hidden="true"><path d="${d > 0 ? "M3 7.5 8 2.5l5 5" : "M3 2.5 8 7.5l5-5"}"/></svg>`;

let coef = Array.isArray(etude.answer) && etude.answer.length === species.length ? etude.answer.map((x) => Math.max(1, Math.min(max, Number(x) || 1))) : species.map(() => 1);

// The equation: two sides that each stay on one line, so a narrow card breaks at the arrow.
const term = (f, k) => `
  <span class="bl-term" data-k="${k}">
    <span class="bl-coef-box">
      <button type="button" class="bl-step up" data-d="1" tabindex="-1" aria-label="More ${etude.escape(f)}">${chevron(1)}</button>
      <input class="bl-coef" inputmode="numeric" enterkeyhint="done" aria-label="Coefficient of ${etude.escape(f)}" value="${coef[k]}" autocomplete="off">
      <button type="button" class="bl-step down" data-d="-1" tabindex="-1" aria-label="Fewer ${etude.escape(f)}">${chevron(-1)}</button>
    </span>
    <span class="bl-formula">${tex(formulaTex(f))}</span>
  </span>`;
const side = (list, offset) => list.map((f, i) => (i ? `<span class="bl-plus">${tex("+")}</span>` : "") + term(f, offset + i)).join("");
const eq = etude.$(".bl-eq");
eq.innerHTML =
  `<span class="bl-side">${side(view.reactants, 0)}</span>` +
  `<span class="bl-side"><span class="bl-arrow">${tex("\\longrightarrow")}</span>${side(view.products, nl)}</span>`;
const inputs = etude.$$(".bl-coef");
const terms = etude.$$(".bl-term");

// The ledger: one row per element. The two counts meet in the middle around =, < or >, and a bar
// grows outward from each, so a balanced row is symmetric at a glance.
const ledger = etude.$(".bl-ledger");
ledger.innerHTML =
  `<div class="bl-row bl-head"><span class="el">Atom</span><span class="hl">Reactants</span><span class="rel">vs</span><span class="hr">Products</span></div>` +
  view.elements.map((e) => `
    <div class="bl-row" data-e="${etude.escape(e)}">
      <span class="el">${tex("\\mathrm{" + e + "}")}</span>
      <span class="track l"><i class="bar"></i></span>
      <span class="n l"></span>
      <span class="rel"></span>
      <span class="n r"></span>
      <span class="track r"><i class="bar"></i></span>
      <span class="st" aria-hidden="true"></span>
    </div>`).join("") +
  `<div class="bl-sum"></div>`;
const rows = etude.$$(".bl-row:not(.bl-head)");
const sum = etude.$(".bl-sum");
const CHECK = `<svg viewBox="0 0 16 16"><path d="M3.5 8.5l3 3 6-7"/></svg>`;

const count = () =>
  view.elements.map((e) => {
    let left = 0, right = 0;
    view.atoms.forEach((a, k) => (k < nl ? (left += (a[e] ?? 0) * coef[k]) : (right += (a[e] ?? 0) * coef[k])));
    return { e, left, right };
  });
const render = () => {
  inputs.forEach((el, k) => {
    if (document.activeElement !== el || el.value !== "") el.value = String(coef[k]);
    el.style.width = `${Math.max(1, String(coef[k]).length) * 0.52 + 0.42}em`;
    terms[k].classList.toggle("is-one", coef[k] === 1);
    terms[k].querySelector(".down").disabled = etude.mode !== "answer" || coef[k] <= 1;
    terms[k].querySelector(".up").disabled = etude.mode !== "answer" || coef[k] >= max;
  });
  const t = count();
  const scale = Math.max(1, ...t.map((x) => Math.max(x.left, x.right)));
  let ok = 0;
  t.forEach((x, i) => {
    const r = rows[i], good = x.left === x.right;
    ok += good;
    r.classList.toggle("ok", good);
    r.classList.toggle("more-l", x.left > x.right);
    r.classList.toggle("more-r", x.right > x.left);
    r.querySelector(".n.l").textContent = x.left;
    r.querySelector(".n.r").textContent = x.right;
    r.querySelector(".track.l .bar").style.width = `${(x.left / scale) * 100}%`;
    r.querySelector(".track.r .bar").style.width = `${(x.right / scale) * 100}%`;
    r.querySelector(".rel").textContent = good ? "=" : x.left < x.right ? "<" : ">";
    r.querySelector(".st").innerHTML = good ? CHECK : "";
    r.setAttribute("aria-label", `${x.e}: ${x.left} on the left, ${x.right} on the right${good ? ", balanced" : ""}`);
  });
  const done = ok === t.length;
  ledger.classList.toggle("all-ok", done);
  sum.textContent = done ? "Every element balances." : `${ok} of ${t.length} balanced.`;
};
const set = (k, v) => {
  if (etude.mode !== "answer") return;
  coef[k] = Math.max(1, Math.min(max, Math.round(v) || 1));
  render();
};

eq.addEventListener("click", (e) => {
  const b = e.target.closest(".bl-step");
  if (!b || b.disabled) return;
  const k = Number(b.closest(".bl-term").dataset.k);
  set(k, coef[k] + Number(b.dataset.d));
});
// A tap on the formula focuses its coefficient, so the whole term is a target.
eq.addEventListener("pointerdown", (e) => {
  const f = e.target.closest(".bl-formula");
  if (!f || etude.mode !== "answer") return;
  e.preventDefault();
  f.closest(".bl-term").querySelector(".bl-coef").focus();
});
inputs.forEach((el, k) => {
  el.addEventListener("input", () => {
    const v = el.value.replace(/\D/g, "").slice(0, 2);
    el.value = v;
    if (v) set(k, Number(v));
  });
  el.addEventListener("blur", render);
  el.addEventListener("focus", () => el.select());
  el.addEventListener("keydown", (e) => {
    if (e.key === "ArrowUp" || e.key === "ArrowDown") {
      e.preventDefault();
      set(k, coef[k] + (e.key === "ArrowUp" ? 1 : -1));
      el.select();
    } else if (e.key === "ArrowRight" && el.selectionStart === el.value.length) {
      e.preventDefault();
      inputs[(k + 1) % inputs.length].focus();
    } else if (e.key === "ArrowLeft" && el.selectionStart === 0) {
      e.preventDefault();
      inputs[(k - 1 + inputs.length) % inputs.length].focus();
    } else if (e.key === "Enter") {
      e.preventDefault();
      etude.submit();
    }
  });
});

render();
etude.getAnswer(() => coef.slice());

etude.onResult(({ grade, key, answer }) => {
  const preview = document.body.dataset.preview === "1";
  const sol = key.solution;
  const given = Array.isArray(answer) && answer.length === species.length;
  // A preview with no attempt shows the balanced equation itself.
  coef = given ? answer.map(Number) : sol.slice();
  inputs.forEach((el) => (el.disabled = true));
  render();
  const d = grade?.details ?? {};
  const state = preview || !given ? "" : grade?.score >= 1 ? "right" : d.balanced ? "near" : "wrong";
  if (state) eq.classList.add(state);
  if (state === "near") {
    ledger.classList.add("near");
    sum.textContent = `Every element balances, but every coefficient divides by ${d.divisor}.`;
  }
  if (state === "wrong" || state === "near") terms.forEach((t, k) => t.classList.toggle("off", coef[k] !== sol[k]));
  // The balanced equation, typeset; coefficients that differ from the learner's are marked.
  const mark = state === "wrong" || state === "near";
  const piece = (k) => {
    const c = sol[k], hit = mark && c !== coef[k];
    const n = c === 1 && !hit ? "" : `<span class="c${hit ? " hit" : ""}">${c}</span>`;
    return `<span class="t">${n}${tex(formulaTex(species[k]))}</span>`;
  };
  const half = (from, to) => [...Array(to - from).keys()].map((i) => (i ? `<span class="op">${tex("+")}</span>` : "") + piece(from + i)).join("");
  // Right answers are already on screen above; say so instead of repeating the equation.
  if (state === "right") {
    etude.$(".bl-answer").innerHTML = `<p class="bl-note ok">${CHECK}Balanced, with the smallest whole numbers.</p>`;
    return;
  }
  etude.$(".bl-answer").innerHTML =
    `<div class="e-section-title">${state === "near" ? "In lowest terms" : "The balanced equation"}</div>` +
    `<div class="bl-final"><span class="s">${half(0, nl)}</span><span class="s"><span class="op">${tex("\\longrightarrow")}</span>${half(nl, species.length)}</span></div>` +
    (state === "near" ? `<p class="bl-note">Divide each of yours by ${d.divisor}.</p>` : "") +
    (state === "wrong" ? `<p class="bl-note">The numbers in pink are where yours differed.</p>` : "");
});

