const log = view.scale === "log";
const slider = etude.$(".es-slider");
const out = etude.$(".es-value");
const N = 1000;
const lmin = log ? Math.log10(view.min) : 0, lmax = log ? Math.log10(view.max) : 0;

// A step of 1, 2 or 5 times a power of ten, about a thousandth of the range.
const niceStep = (span) => {
  const raw = span / N, p = Math.pow(10, Math.floor(Math.log10(raw)));
  return [1, 2, 5, 10].map((m) => m * p).find((s) => s >= raw);
};
const step = view.step || niceStep(view.max - view.min);
const sig = (x, d) => (x === 0 ? 0 : Number(x.toPrecision(d)));
const toValue = (p) => {
  const t = p / N;
  if (log) return sig(Math.pow(10, lmin + (lmax - lmin) * t), 2);
  return Math.round((view.min + (view.max - view.min) * t) / step) * step;
};
const toPos = (v) => {
  const t = log ? (Math.log10(v) - lmin) / (lmax - lmin) : (v - view.min) / (view.max - view.min);
  return Math.max(0, Math.min(1, t));
};

// "3.2 million", "8,850", "0.004".
const WORDS = [[1e12, "trillion"], [1e9, "billion"], [1e6, "million"]];
const fmt = (v) => {
  const a = Math.abs(v);
  for (const [n, w] of WORDS) if (a >= n) return `${sig(v / n, a / n >= 100 ? 3 : 2).toLocaleString("en")} ${w}`;
  if (a >= 1) return sig(v, log ? 2 : 6).toLocaleString("en");
  return String(sig(v, 2));
};
const sci = (v) => {
  const e = Math.floor(Math.log10(Math.abs(v)));
  const m = sig(v / Math.pow(10, e), 2);
  return m === 1 ? `10^{${e}}` : `${m} \\times 10^{${e}}`;
};
const unit = view.unit ? " " + view.unit : "";

const show = () => {
  const v = toValue(Number(slider.value));
  out.innerHTML = `<span class="num">${etude.escape(fmt(v))}</span><span class="unit">${etude.escape(unit)}</span>` +
    (log && Math.abs(v) >= 1e4 ? `<span class="sci">${etude.mdInline("$" + sci(v) + "$")}</span>` : "");
  slider.setAttribute("aria-valuetext", fmt(v) + unit);
};

// Ends, and powers of ten along a log track.
etude.$(".es-ends .lo").textContent = fmt(view.min) + unit;
etude.$(".es-ends .hi").textContent = fmt(view.max) + unit;
const marks = etude.$(".es-marks");
const at = (t) => `calc(${t * 100}% + ${(0.5 - t) * 1.5}rem)`;
if (log) {
  const decades = Math.floor(lmax) - Math.ceil(lmin);
  const every = decades > 8 ? 2 : 1;
  for (let e = Math.ceil(lmin); e <= Math.floor(lmax); e++) {
    if ((e - Math.ceil(lmin)) % every) continue;
    const t = (e - lmin) / (lmax - lmin);
    const m = document.createElement("span");
    m.className = "es-decade";
    m.style.left = at(t);
    m.innerHTML = `<i></i><b>${etude.mdInline(`$10^{${e}}$`)}</b>`;
    marks.append(m);
  }
  etude.$(".es-hint").textContent = "Each tick is ten times the last. Arrow keys nudge the slider.";
} else etude.$(".es-hint").textContent = "Drag the slider, or use the arrow keys.";
etude.$(".es").classList.toggle("is-log", log);

let touched = false;
const startPos = Number.isFinite(Number(etude.answer)) && etude.answer !== null ? Math.round(toPos(Number(etude.answer)) * N) : N / 2;
slider.value = String(startPos);
slider.addEventListener("input", () => {
  touched = true;
  show();
  etude.setReady(true);
});
show();
etude.setReady(etude.answer !== null);
etude.getAnswer(() => toValue(Number(slider.value)));

etude.onResult(({ grade, key, answer }) => {
  slider.disabled = true;
  const preview = document.body.dataset.preview === "1";
  const truth = key.answer;
  const guess = Number.isFinite(Number(answer)) && answer !== null ? Number(answer) : toValue(Number(slider.value));
  if (Number.isFinite(guess)) slider.value = String(Math.round(toPos(guess) * N));
  show();

  // The full-credit band and the true value on the track.
  const t = key.tolerance;
  const [a, b] = log
    ? [toPos(truth / Math.pow(10, t)), toPos(truth * Math.pow(10, t))]
    : [toPos(truth - t * (view.max - view.min)), toPos(truth + t * (view.max - view.min))];
  const band = document.createElement("span");
  band.className = "es-band";
  band.style.left = at(a);
  band.style.width = `calc(${(b - a) * 100}% - ${(b - a) * 1.5}rem)`;
  marks.append(band);
  const tm = document.createElement("span");
  tm.className = "es-truth";
  tm.style.left = at(toPos(truth));
  marks.append(tm);

  const tone = preview ? "" : grade.score >= 1 ? "good" : grade.score > 0 ? "near" : "far";
  if (tone) out.classList.add(tone);
  if (preview) slider.classList.add("hide-thumb");
  const words = grade?.details?.words;
  const truthTex = log && Math.abs(truth) >= 1e4 ? ` <span class="e-muted">${etude.mdInline("$" + sci(truth) + "$")}</span>` : "";
  etude.$(".es-verdict").innerHTML =
    `<div class="e-section-title">Actual</div><div class="es-actual">${etude.escape(fmt(truth) + unit)}${truthTex}</div>` +
    (!preview && words ? `<div class="es-words ${tone}">You said ${etude.escape(fmt(guess) + unit)}: ${etude.escape(words)}.</div>` : "");
});

grader.code:
const given = Array.isArray(answer) ? answer.map(String) : [];
const order = key.order;
let k = 0;
while (k < order.length && given[k] === order[k]) k++;
// The start node is placed for the learner, so it doesn't earn credit.
const score = order.length > 1 ? Math.max(0, k - 1) / (order.length - 1) : 1;
let feedback;
const name = view.algorithm === "bfs" ? "BFS" : "DFS";
if (k < order.length) {
  if (k >= given.length) feedback = `Correct for the first ${k} nodes, then the order stopped. ${name} visits ${order[k]} next.`;
  else feedback = `Correct for the first ${k} node${k === 1 ? "" : "s"}. Step ${k + 1} is ${order[k]}, not ${given[k]}. (${Math.max(0, k - 1)} of ${order.length - 1} moves after the start.)`;
}
return { score, feedback, details: { prefix: k, given } };

types.prepare:
// A connected graph on a jittered 3×3 grid. Edges only join neighbouring cells (and at most one
// diagonal per square), so no edge crosses a node or another edge.
const W = 3, H = 3;
const want = Number(fields.size);
const n = want >= 6 && want <= 9 ? Math.round(want) : rng.int(6, 9);
const cell = (c, r) => r * W + c;
const neigh = (i) => {
  const c = i % W, r = Math.floor(i / W), out = [];
  for (const [dc, dr] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
    const cc = c + dc, rr = r + dr;
    if (cc >= 0 && cc < W && rr >= 0 && rr < H) out.push(cell(cc, rr));
  }
  return out;
};
// Grow a connected set of n cells from a random one.
const cells = [rng.int(0, W * H - 1)];
while (cells.length < n) {
  const frontier = [...new Set(cells.flatMap(neigh))].filter((x) => !cells.includes(x));
  cells.push(rng.pick(frontier));
}
const used = new Set(cells);
const cand = [];
for (const a of cells) {
  const c = a % W, r = Math.floor(a / W);
  if (c + 1 < W && used.has(cell(c + 1, r))) cand.push([a, cell(c + 1, r)]);
  if (r + 1 < H && used.has(cell(c, r + 1))) cand.push([a, cell(c, r + 1)]);
  // One diagonal per square at most.
  if (c + 1 < W && r + 1 < H) {
    const d1 = [a, cell(c + 1, r + 1)], d2 = [cell(c + 1, r), cell(c, r + 1)];
    const ok1 = used.has(d1[1]), ok2 = used.has(d2[0]) && used.has(d2[1]);
    if (ok1 && ok2) cand.push(rng.bool() ? d1 : d2);
    else if (ok1) cand.push(d1);
    else if (ok2) cand.push(d2);
  }
}
// Random spanning tree over the candidates (Kruskal on a shuffle), then a few extra edges.
const parent = {};
const find = (x) => (parent[x] === undefined || parent[x] === x ? x : (parent[x] = find(parent[x])));
const edges = [], extra = [];
for (const e of rng.shuffle(cand)) {
  const a = find(e[0]), b = find(e[1]);
  if (a !== b) { parent[a] = b; edges.push(e); } else extra.push(e);
}
const extras = Math.min(extra.length, rng.int(1, 3));
edges.push(...extra.slice(0, extras));

// Letters are assigned at random so alphabetical order isn't left-to-right.
const letters = rng.shuffle("ABCDEFGHI".slice(0, n).split(""));
const label = Object.fromEntries(cells.map((c, i) => [c, letters[i]]));
const nodes = cells.map((c) => ({
  id: label[c],
  x: 66 + (c % W) * 120 + rng.int(-14, 14),
  y: 48 + Math.floor(c / W) * 102 + rng.int(-12, 12),
})).sort((a, b) => a.id.localeCompare(b.id));
const edgeList = edges.map(([a, b]) => [label[a], label[b]].sort()).sort((p, q) => (p[0] + p[1]).localeCompare(q[0] + q[1]));

const adj = Object.fromEntries(nodes.map((v) => [v.id, []]));
for (const [a, b] of edgeList) { adj[a].push(b); adj[b].push(a); }
for (const k in adj) adj[k].sort();

let algo = String(fields.algorithm ?? "bfs").toLowerCase();
if (algo !== "bfs" && algo !== "dfs") algo = rng.pick(["bfs", "dfs"]);
const start = rng.pick(nodes).id;
const order = [], tree = [], seen = new Set([start]);
if (algo === "bfs") {
  const q = [start];
  while (q.length) {
    const v = q.shift();
    order.push(v);
    for (const w of adj[v]) if (!seen.has(w)) { seen.add(w); tree.push([v, w]); q.push(w); }
  }
} else {
  const visit = (v) => {
    order.push(v);
    for (const w of adj[v]) if (!seen.has(w)) { seen.add(w); tree.push([v, w]); visit(w); }
  };
  visit(start);
}
return {
  view: { algorithm: algo, start, nodes, edges: edgeList, note: fields.note ?? "" },
  key: { order, tree, explanation: fields.explanation ?? "" },
};

template.css:
.sc-eyebrow { font-size: 0.72rem; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: var(--highlight); margin-bottom: -0.5rem; }
.sc-how { font-size: 0.85rem; color: var(--muted-foreground); border-top: 1px solid var(--border); padding-top: 0.75rem; margin: 0.25rem 0 0; }

/* Code should read literally: no fused glyphs from ligature fonts. */
#card, #card * { font-variant-ligatures: none; font-feature-settings: "liga" 0, "calt" 0; }

.gw-prompt .rule { color: var(--muted-foreground); font-size: 0.95rem; }
.gw-stage { display: flex; justify-content: center; }
.gw-svg { width: 100%; max-width: 440px; height: auto; display: block; touch-action: manipulation; user-select: none; -webkit-user-select: none; -webkit-tap-highlight-color: transparent; }

.gw-edge { stroke: color-mix(in oklab, var(--foreground) 40%, transparent); stroke-width: 2.25; stroke-linecap: round; transition: stroke 0.3s, stroke-width 0.3s; }
.gw-edge.tree { stroke: var(--highlight); stroke-width: 3.5; }

.gw-node { cursor: pointer; outline: none; }
.gw-node .hit { fill: transparent; }
.gw-node .disc { fill: var(--background); stroke: color-mix(in oklab, var(--foreground) 45%, transparent); stroke-width: 2; transition: fill 0.2s, stroke 0.2s; }
.gw-node .lbl { fill: var(--foreground); font: 600 17px var(--font-sans); text-anchor: middle; dominant-baseline: central; pointer-events: none; }
.gw-node .num { fill: var(--background); font: 700 11px var(--font-sans); text-anchor: middle; dominant-baseline: central; pointer-events: none; }
.gw-node .badge { fill: var(--highlight); stroke: var(--background); stroke-width: 2.5; opacity: 0; transition: opacity 0.15s; }
.gw-node.picked .badge, .gw-node.picked .num { opacity: 1; }
.gw-node .num { opacity: 0; }
.gw-node.picked .disc { stroke: var(--highlight); fill: color-mix(in oklab, var(--highlight) 14%, var(--background)); }
.gw-node.start .disc { stroke: var(--foreground); stroke-width: 3; }
.gw-node.last .disc { stroke-dasharray: 4 3; }
.gw-node:hover .disc { stroke: var(--foreground); }
.gw-node:focus-visible .disc { stroke: var(--ring); stroke-width: 4; }
[data-mode="result"] .gw-node { cursor: default; }
.gw-node.ok .badge { fill: var(--success); }
.gw-node.bad .badge { fill: var(--danger); }
.gw-node.after .badge { fill: var(--muted-foreground); }
.gw-node.lit .disc { fill: color-mix(in oklab, var(--highlight) 30%, var(--background)); stroke: var(--highlight); stroke-width: 3; }
.gw-node.lit .lbl { fill: var(--foreground); }
.gw-node.lit-now .disc { stroke-width: 5; }

.hop { display: inline-flex; align-items: center; gap: 0.35rem; }
.gw-seq { display: flex; flex-wrap: wrap; gap: 0.35rem; align-items: center; min-height: 2rem; font-family: var(--font-mono); font-size: 0.95rem; }
.gw-seq .step, .gw-truth .step { display: inline-flex; align-items: center; justify-content: center; min-width: 1.9rem; height: 1.9rem; padding: 0 0.4rem; border: 1px solid var(--border); border-radius: 0.45rem; }
.gw-seq .arrow, .gw-truth .arrow { color: var(--muted-foreground); font: 0.85rem/1 var(--font-sans); }
.gw-seq .step.ok { border-color: color-mix(in oklab, var(--success) 70%, transparent); background: color-mix(in oklab, var(--success) 10%, transparent); }
.gw-seq .step.after { color: var(--muted-foreground); border-style: dashed; }
.gw-seq .step.bad { border-color: color-mix(in oklab, var(--danger) 70%, transparent); background: color-mix(in oklab, var(--danger) 10%, transparent); }
.gw-seq .empty { color: var(--muted-foreground); font-family: var(--font-sans); font-size: 0.9rem; }
.gw-truth { display: flex; flex-wrap: wrap; gap: 0.35rem; align-items: center; font-family: var(--font-mono); }
.gw-truth .step { transition: background 0.2s, border-color 0.2s; }
.gw-truth .step.lit { border-color: color-mix(in oklab, var(--foreground) 55%, transparent); background: color-mix(in oklab, var(--foreground) 7%, transparent); }
.gw-seq-wrap { margin-top: -0.25rem; }
.gw-help { font-size: 0.82rem; margin: -0.5rem 0 0; }

template.js:
const { view } = etude;
const NS = "http://www.w3.org/2000/svg";
const svg = etude.$(".gw-svg");
const seqEl = etude.$(".gw-seq");
const name = view.algorithm === "bfs" ? "breadth-first search (BFS)" : "depth-first search (DFS)";
etude.$(".gw-prompt").innerHTML =
  etude.md(`Tap the nodes in the order **${name}** visits them, starting from **${view.start}**.`) +
  `<p class="rule">When a node has several unvisited neighbours, take them in alphabetical order.</p>` +
  (view.note ? etude.md(view.note) : "");

const pos = Object.fromEntries(view.nodes.map((n) => [n.id, n]));
const nb = Object.fromEntries(view.nodes.map((n) => [n.id, []]));
for (const [a, b] of view.edges) { nb[a].push(b); nb[b].push(a); }
for (const k in nb) nb[k].sort();
const el = (tag, attrs, parent) => {
  const e = document.createElementNS(NS, tag);
  for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, v);
  parent?.appendChild(e);
  return e;
};
const edgeEls = {};
const edgesG = el("g", {}, svg);
for (const [a, b] of view.edges) {
  edgeEls[[a, b].sort().join("")] = el("line", { class: "gw-edge", x1: pos[a].x, y1: pos[a].y, x2: pos[b].x, y2: pos[b].y }, edgesG);
}
const nodeEls = {};
for (const n of view.nodes) {
  const g = el("g", { class: "gw-node", tabindex: "0", role: "button", "aria-label": `Node ${n.id}`, "data-id": n.id }, svg);
  el("circle", { class: "hit", cx: n.x, cy: n.y, r: 30 }, g);
  el("circle", { class: "disc", cx: n.x, cy: n.y, r: 20 }, g);
  el("text", { class: "lbl", x: n.x, y: n.y }, g).textContent = n.id;
  // The order badge goes in the diagonal corner farthest from this node's edges.
  const angles = nb[n.id].map((m) => Math.atan2(pos[m].y - n.y, pos[m].x - n.x));
  const gap = (a) => Math.min(...angles.map((b) => Math.abs(Math.atan2(Math.sin(a - b), Math.cos(a - b)))), Math.PI);
  const corner = [-Math.PI / 4, -3 * Math.PI / 4, Math.PI / 4, 3 * Math.PI / 4].reduce((best, a) => (gap(a) > gap(best) + 0.01 ? a : best));
  const bx = n.x + 27 * Math.cos(corner), by = n.y + 27 * Math.sin(corner);
  el("circle", { class: "badge", cx: bx, cy: by, r: 10 }, g);
  el("text", { class: "num", x: bx, y: by + 0.5 }, g);
  nodeEls[n.id] = g;
}

// The start node is given: the order always begins there.
let seq = [view.start];
if (Array.isArray(etude.answer) && etude.answer[0] === view.start) seq = etude.answer.filter((id) => pos[id]);

const paint = (marks) => {
  for (const [id, g] of Object.entries(nodeEls)) {
    const i = seq.indexOf(id);
    g.classList.toggle("picked", i >= 0);
    g.classList.toggle("start", id === view.start);
    g.classList.toggle("last", etude.mode === "answer" && i >= 1 && i === seq.length - 1);
    g.querySelector(".num").textContent = i >= 0 ? String(i + 1) : "";
    g.setAttribute("aria-label", `Node ${id}${i >= 0 ? `, visited ${i + 1}` : ""}; neighbours ${nb[id].join(" ")}`);
    if (marks) { g.classList.toggle("ok", marks[id] === "ok"); g.classList.toggle("bad", marks[id] === "bad"); g.classList.toggle("after", marks[id] === "after"); }
  }
  // Each arrow travels with the step after it, so a wrapped row never ends on an arrow.
  seqEl.innerHTML = seq.map((id, i) => {
    const cls = marks ? marks[id] ?? "" : "";
    return `<span class="hop">${i ? `<span class="arrow">→</span>` : ""}<span class="step ${cls}">${id}</span></span>`;
  }).join("") + (seq.length === 1 && etude.mode === "answer" ? `<span class="arrow">→</span><span class="empty">tap the next node</span>` : "");
  etude.setReady(etude.mode === "answer" && seq.length > 1);
};
const tap = (id) => {
  if (etude.mode !== "answer") return;
  const i = seq.indexOf(id);
  if (i < 0) seq.push(id);
  else if (i === seq.length - 1 && i > 0) seq.pop();
  else return;
  paint();
};
svg.addEventListener("click", (e) => {
  const g = e.target.closest(".gw-node");
  if (g) tap(g.dataset.id);
});
window.addEventListener("keydown", (e) => {
  if (etude.mode !== "answer" || e.ctrlKey || e.metaKey || e.altKey) return;
  const k = e.key.toUpperCase();
  if (k.length === 1 && pos[k]) { e.preventDefault(); tap(k); }
  else if (e.key === "Backspace" && seq.length > 1) { e.preventDefault(); tap(seq[seq.length - 1]); }
  else if ((e.key === "Enter" || e.key === " ") && e.target.closest?.(".gw-node")) { e.preventDefault(); tap(e.target.closest(".gw-node").dataset.id); }
});
paint();
etude.getAnswer(() => seq.slice());

// After grading: mark the attempt, then walk the real order and grow its traversal tree.
let playing = 0;
const play = async (key) => {
  const run = ++playing;
  const truth = etude.$(".gw-truth");
  truth.innerHTML = key.order.map((id, i) => `<span class="hop">${i ? `<span class="arrow">→</span>` : ""}<span class="step" data-id="${id}">${id}</span></span>`).join("");
  Object.values(edgeEls).forEach((l) => l.classList.remove("tree"));
  Object.values(nodeEls).forEach((g) => g.classList.remove("lit", "lit-now"));
  const parentOf = Object.fromEntries(key.tree.map(([p, c]) => [c, p]));
  const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
  for (const id of key.order) {
    if (run !== playing) return;
    if (parentOf[id]) edgeEls[[parentOf[id], id].sort().join("")]?.classList.add("tree");
    Object.values(nodeEls).forEach((g) => g.classList.remove("lit-now"));
    nodeEls[id].classList.add("lit", "lit-now");
    truth.querySelector(`[data-id="${id}"]`)?.classList.add("lit");
    if (!reduce) await new Promise((r) => setTimeout(r, 520));
  }
  nodeEls[key.order[key.order.length - 1]].classList.remove("lit-now");
};
etude.onResult(({ key, answer, grade }) => {
  if (Array.isArray(answer)) seq = answer.filter((id) => pos[id]);
  const prefix = grade?.details?.prefix ?? 0;
  // Right up to the first mistake, the mistake itself, then the rest left unjudged.
  const marks = {};
  seq.forEach((id, i) => (marks[id] = i < prefix ? "ok" : i === prefix ? "bad" : "after"));
  for (const g of Object.values(nodeEls)) g.removeAttribute("tabindex");
  paint(grade?.details ? marks : null);
  etude.$(".gw-replay")?.addEventListener("click", () => play(key));
  play(key);
});

grader.code:
const pick = view.options.find((o) => o.id === answer);
if (!pick) return { score: 0, feedback: "No interval picked." };
const ok = answer === key.answer;
const size = (id) => id.slice(1);
let feedback;
if (!ok) {
  feedback = size(answer) === size(key.answer) && key.answer !== "TT"
    ? `Right size, wrong quality: it was a ${key.name}, not a ${pick.name}.`
    : `It was a ${key.name} (${key.semis} semitone${key.semis === 1 ? "" : "s"}), not a ${pick.name}.`;
}
return { score: ok ? 1 : 0, feedback, details: { picked: answer } };

types.prepare:
const LET = "CDEFGAB", PCS = [0, 2, 4, 5, 7, 9, 11];
const midiOf = (n) => 12 * (n.oct + 1) + PCS[LET.indexOf(n.letter)] + n.acc;
const above = (n, steps, semis) => {
  const li = LET.indexOf(n.letter) + steps;
  const t = { letter: LET[li % 7], oct: n.oct + Math.floor(li / 7), acc: 0 };
  t.acc = midiOf(n) + semis - midiOf(t);
  return t;
};
const ACC = { "-2": "𝄫", "-1": "♭", 0: "", 1: "♯", 2: "𝄪" };
const TEX = { "-2": "\\flat\\flat", "-1": "\\flat", 0: "", 1: "\\sharp", 2: "\\sharp\\sharp" };
const txt = (n) => `${n.letter}${ACC[n.acc]}${n.oct}`;
const tex = (n) => `\\mathrm{${n.letter}}${TEX[n.acc]}_{${n.oct}}`;

// [id, name, letter steps, semitones]
const ALL = [
  ["m2", "minor 2nd", 1, 1], ["M2", "major 2nd", 1, 2], ["m3", "minor 3rd", 2, 3], ["M3", "major 3rd", 2, 4],
  ["P4", "perfect 4th", 3, 5], ["TT", "tritone", 3, 6], ["P5", "perfect 5th", 4, 7], ["m6", "minor 6th", 5, 8],
  ["M6", "major 6th", 5, 9], ["m7", "minor 7th", 6, 10], ["M7", "major 7th", 6, 11], ["P8", "octave", 7, 12],
];
const BASIC = ["M2", "m3", "M3", "P4", "P5", "M6", "P8"];
const set = fields.set === "all" ? ALL : ALL.filter((i) => BASIC.includes(i[0]));
const [id, name, steps, semis] = rng.pick(set);

// A root between C3 and G4, mostly natural, spelled so the top note needs at most one sharp or flat.
let root, top;
do {
  root = { letter: rng.pick([...LET]), oct: rng.pick([3, 3, 4]), acc: rng.bool(0.25) ? rng.pick([-1, 1]) : 0 };
  top = above(root, steps, semis);
} while (Math.abs(top.acc) > 1 || midiOf(root) < 48 || midiOf(root) > 67 || (root.letter === "B" && root.acc === 1) || (root.letter === "E" && root.acc === 1) || (root.letter === "C" && root.acc === -1) || (root.letter === "F" && root.acc === -1));

const dirs = { up: "up", down: "down", harmonic: "harmonic" };
const direction = dirs[fields.direction] ?? rng.pick(["up", "up", "down", "harmonic"]);
return {
  view: {
    prompt: fields.prompt ?? "",
    direction,
    low: midiOf(root),
    high: midiOf(top),
    options: set.map(([i, n]) => ({ id: i, name: n })),
  },
  key: {
    answer: id, name, semis,
    first: direction === "down" ? txt(top) : txt(root), second: direction === "down" ? txt(root) : txt(top),
    firstTex: direction === "down" ? tex(top) : tex(root), secondTex: direction === "down" ? tex(root) : tex(top),
    lowText: txt(root), highText: txt(top),
    explanation: fields.explanation ?? "",
  },
};

