/* Round play button. */
.play-btn { display: inline-flex; align-items: center; gap: 0.55rem; padding: 0.7rem 1.3rem 0.7rem 1rem; min-height: 48px; border-radius: 999px; border: 1px solid color-mix(in oklab, var(--highlight) 55%, var(--border)); background: color-mix(in oklab, var(--highlight) 12%, transparent); color: var(--foreground); font: 600 1rem var(--font-sans); cursor: pointer; -webkit-tap-highlight-color: transparent; touch-action: manipulation; transition: background 0.15s, transform 0.08s; }
