template.js:
const { view } = etude;
const q = etude.$(".sp-q");
const input = etude.$(".sp-input");
const startBtn = etude.$(".sp-start");
const fill = etude.$(".sp-fill");
const timeEl = etude.$(".sp-time");
const countEl = etude.$(".sp-count");
const total = view.seconds * 1000;

const answers = [];
let i = 0, t0 = 0, running = false, finished = false, raf = 0, endTimer = 0;
q.textContent = "ready?";
q.classList.add("idle");
timeEl.textContent = `${view.seconds.toFixed(1)} s`;
countEl.textContent = `0 answered`;
etude.setReady(false);

const show = () => {
  q.classList.remove("idle", "pop");
  void q.offsetWidth;
  q.textContent = `${view.problems[i]} =`;
  q.classList.add("pop");
};
const tick = () => {
  const left = Math.max(0, total - (performance.now() - t0));
  fill.style.transform = `scaleX(${left / total})`;
  fill.classList.toggle("low", left < 5000);
  timeEl.textContent = `${(left / 1000).toFixed(1)} s`;
  if (left <= 0) return finish();
  raf = requestAnimationFrame(tick);
};
const finish = () => {
  if (finished) return;
  finished = true;
  running = false;
  cancelAnimationFrame(raf);
  clearTimeout(endTimer);
  // A half-typed answer when the clock runs out still counts.
  if (input.value.trim()) answers.push(input.value.trim());
  input.disabled = true;
  fill.style.transform = "scaleX(0)";
  timeEl.textContent = "0.0 s";
  q.textContent = "time!";
  quietUntil = performance.now() + 1500;
  etude.submit({ answers: answers.slice() });
};
const start = () => {
  if (running || finished || etude.mode !== "answer") return;
  running = true;
  startBtn.hidden = true;
  input.disabled = false;
  input.focus();
  t0 = performance.now();
  show();
  raf = requestAnimationFrame(tick);
  // Backup for when animation frames pause (hidden tab).
  endTimer = setTimeout(finish, total + 50);
};
startBtn.addEventListener("click", start);
// The card frame is sandboxed without forms, so Enter is handled on the input itself.
const next = () => {
  if (!running) return;
  const v = input.value.trim();
  if (!v) return;
  answers.push(v);
  input.value = "";
  countEl.textContent = `${answers.length} answered`;
  i++;
  if (i >= view.problems.length) return finish();
  show();
};
input.addEventListener("keydown", (e) => {
  if (e.key === "Enter" && !e.ctrlKey && !e.metaKey) { e.preventDefault(); next(); }
});
// Enter or Space starts the round; while it runs, Enter belongs to the input.
// Right after the buzzer, Enter and Space are swallowed for a moment: someone mid-answer
// would otherwise rate the card before seeing their results.
let quietUntil = 0;
window.addEventListener("keydown", (e) => {
  if (e.ctrlKey || e.metaKey || e.altKey) return;
  if ((e.key === "Enter" || e.key === " ") && (performance.now() < quietUntil || (finished && etude.mode === "answer"))) { e.preventDefault(); return; }
  if (etude.mode !== "answer") return;
  if (!running && !finished && (e.key === "Enter" || e.key === " ")) { e.preventDefault(); start(); }
});
etude.getAnswer(() => ({ answers: [...answers, ...(running && input.value.trim() ? [input.value.trim()] : [])] }));

etude.onResult(({ grade, key, answer }) => {
  if (finished) quietUntil = Math.max(quietUntil, performance.now() + 1200);
  running = false;
  finished = true;
  cancelAnimationFrame(raf);
  clearTimeout(endTimer);
  const d = grade?.details;
  const given = Array.isArray(answer?.answers) ? answer.answers : [];
  const rows = d?.rows ?? given.map((g, k) => ({ q: view.problems[k], given: String(g), want: key.answers[k], ok: null }));
  const correct = d?.correct ?? rows.filter((r) => r.ok).length;
  if (d) {
    etude.$(".sp-score .n").textContent = `${correct} right`;
    etude.$(".sp-score .of").textContent = `target ${view.target}`;
    const acc = d.answered ? Math.round((100 * correct) / d.answered) : 0;
    etude.$(".sp-line").textContent = `${d.answered} answered in ${view.seconds} seconds, ${acc}% accurate.`;
  } else {
    // Previews have no attempt: show what a round looks like.
    etude.$(".sp-score .n").textContent = `${view.seconds}s`;
    etude.$(".sp-score .of").textContent = `target ${view.target}`;
    etude.$(".sp-line").textContent = "The first problems of this round, with their answers.";
  }
  // Show what was attempted, plus the first unanswered problem so the round has an end.
  const shown = rows.length ? rows : view.problems.slice(0, 6).map((p, k) => ({ q: p, given: "", want: key.answers[k], ok: null }));
  etude.$(".sp-table").innerHTML = shown.length
    ? shown.map((r) => {
        const cls = r.ok === true ? "ok" : r.given === "" ? "skip" : r.ok === false ? "bad" : "";
        const a = r.ok ? etude.escape(r.given) : `${r.given ? `<s>${etude.escape(r.given)}</s> ` : ""}<span class="want">${r.want}</span>`;
        return `<div class="sp-row ${cls}"><span class="q">${etude.escape(r.q)}</span><span class="a">${a}</span></div>`;
      }).join("")
    : `<div class="sp-empty">No answers this round.</div>`;
});

grader.code:
if (!Number.isInteger(answer)) return { score: 0, feedback: "No note picked." };
const NAMES = ["C", "C♯/D♭", "D", "D♯/E♭", "E", "F", "F♯/G♭", "G", "G♯/A♭", "A", "A♯/B♭", "B"];
const pc = ((answer % 12) + 12) % 12;
const ok = pc === key.pc;
return { score: ok ? 1 : 0, feedback: ok ? undefined : `That's ${NAMES[pc]}; the note is ${key.full}.`, details: { pc } };

types.prepare:
const LET = "CDEFGAB", PCS = [0, 2, 4, 5, 7, 9, 11];
const clef = fields.clef === "bass" ? "bass" : fields.clef === "both" ? rng.pick(["treble", "bass"]) : "treble";
// Diatonic index of the bottom line: E4 in treble, G2 in bass.
const bottom = clef === "treble" ? 7 * 4 + 2 : 7 * 2 + 4;
const ledger = Math.max(0, Math.min(3, Math.round(Number(fields.ledger ?? 2))));
// Position 0 is the bottom line, 8 the top line; each ledger line adds two positions.
const lo = -2 * ledger - 1, hi = 8 + 2 * ledger + 1;
// Mostly on the staff, sometimes on ledger lines.
const pos = ledger && rng.bool(0.35) ? rng.pick([...Array(hi - lo + 1).keys()].map((k) => k + lo).filter((p) => p < -1 || p > 9)) : rng.int(-1, 9);
const d = bottom + pos;
const letter = LET[d % 7], oct = Math.floor(d / 7);
let acc = 0;
if (fields.accidentals === true && rng.bool(0.4)) acc = rng.pick([-1, 1]);
const midi = 12 * (oct + 1) + PCS[d % 7] + acc;
const ACC = { "-1": "♭", 0: "", 1: "♯" }, TEX = { "-1": "\\flat", 0: "", 1: "\\sharp" };
return {
  view: { prompt: fields.prompt ?? "", clef, pos, acc, accidentals: fields.accidentals === true },
  key: {
    pc: ((midi % 12) + 12) % 12, midi,
    name: `${letter}${ACC[acc]}`, full: `${letter}${ACC[acc]}${oct}`, tex: `\\mathrm{${letter}}${TEX[acc]}_{${oct}}`,
    explanation: fields.explanation ?? "",
  },
};

template.css:
.sc-eyebrow { font-size: 0.72rem; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: var(--highlight); margin-bottom: -0.5rem; }
.sc-how { font-size: 0.85rem; color: var(--muted-foreground); border-top: 1px solid var(--border); padding-top: 0.75rem; margin: 0.25rem 0 0; }

/* Piano keyboard (shared by the music types). Keys keep piano colors in every theme: it's an object, not a surface. */
/* Octaves sit side by side as one keyboard; on phones a two-octave keyboard stacks so keys stay tappable. */
.kb { display: flex; flex-wrap: nowrap; justify-content: center; gap: 0; width: 100%; }
.kb-oct { flex: 1 1 0; min-width: 0; max-width: 20rem; height: auto; display: block; touch-action: manipulation; user-select: none; -webkit-user-select: none; }
@media (max-width: 520px) { .kb:not(.kb-nowrap) { flex-wrap: wrap; gap: 0.6rem; } .kb:not(.kb-nowrap) .kb-oct { flex-basis: 100%; max-width: 22rem; } }
.key path { stroke: rgba(0, 0, 0, 0.5); stroke-width: 1; transition: fill 0.12s; cursor: pointer; }
.kb.static .key path { cursor: default; }
.key.white path { fill: #f4f1ea; }
.key.black path { fill: #252321; stroke: #0e0d0c; }
.key .kl { font: 600 7px var(--font-sans); text-anchor: middle; fill: #6d6862; pointer-events: none; }
.key.black .kl { fill: #f1ece4; font-size: 5.5px; }
.key.down path { filter: brightness(0.85); }
.key.white.sel path { fill: color-mix(in oklab, var(--highlight) 55%, #f4f1ea); }
.key.black.sel path { fill: color-mix(in oklab, var(--highlight) 75%, #252321); }
.key.white.ok path { fill: color-mix(in oklab, var(--success) 55%, #f4f1ea); }
.key.black.ok path { fill: color-mix(in oklab, var(--success) 88%, #252321); }
.key.white.bad path { fill: color-mix(in oklab, var(--danger) 68%, #f4f1ea); }
.key.black.bad path { fill: color-mix(in oklab, var(--danger) 88%, #252321); }
.key.white.miss path { fill: color-mix(in oklab, var(--warning) 50%, #f4f1ea); }
.key.black.miss path { fill: color-mix(in oklab, var(--warning) 70%, #252321); }
.key.ok .kl, .key.bad .kl, .key.sel .kl, .key.miss .kl { fill: #1b1a19; font-size: 8px; }
.key.black.ok .kl, .key.black.bad .kl, .key.black.sel .kl, .key.black.miss .kl { fill: #fff; font-size: 6.5px; }

/* Round play button. */
.play-btn { display: inline-flex; align-items: center; gap: 0.55rem; padding: 0.7rem 1.3rem 0.7rem 1rem; min-height: 48px; border-radius: 999px; border: 1px solid color-mix(in oklab, var(--highlight) 55%, var(--border)); background: color-mix(in oklab, var(--highlight) 12%, transparent); color: var(--foreground); font: 600 1rem var(--font-sans); cursor: pointer; -webkit-tap-highlight-color: transparent; touch-action: manipulation; transition: background 0.15s, transform 0.08s; }
.play-btn:hover { background: color-mix(in oklab, var(--highlight) 20%, transparent); }
.play-btn:active { transform: scale(0.97); }
.play-btn:focus-visible { outline: none; box-shadow: 0 0 0 3px color-mix(in oklab, var(--ring) 35%, transparent); }
.play-btn .ic { width: 1.3rem; height: 1.3rem; display: inline-flex; color: var(--highlight); }
.play-btn .ic svg { width: 100%; height: 100%; }
.play-btn.on .ic { animation: pulse 0.6s ease-in-out infinite alternate; }
.play-btn.small { padding: 0.45rem 0.95rem 0.45rem 0.75rem; min-height: 40px; font-size: 0.9rem; }
.play-btn.small .ic { width: 1rem; height: 1rem; }
@keyframes pulse { from { opacity: 1; } to { opacity: 0.35; } }

.st-prompt { font-size: 1.05rem; }
.st-staff svg { width: 100%; max-width: 26rem; height: auto; display: block; margin: 0 auto; color: var(--foreground); overflow: visible; }
.st-staff .sl, .st-staff .ledger { stroke: currentColor; stroke-width: 1; }
.st-staff .ledger { stroke-width: 1.2; }
.st-staff .clef, .st-staff .note path { fill: currentColor; }
.st-staff .note ellipse { fill: currentColor; }
.st-staff .note .stem { stroke: currentColor; stroke-width: 1.3; }
.st-staff .note.ok { color: var(--success); }
.st-staff .note.bad { color: var(--danger); }
.st-kb .kb-oct { max-width: 24rem; }
.st-help { font-size: 0.82rem; margin: -0.5rem 0 0; text-align: center; }
.st-answer { font-size: 1.1rem; }
.st-answer p { margin: 0; }

