      d: `M${ex},${ey} L${ex - h * Math.cos(ang - 0.5)},${ey - h * Math.sin(ang - 0.5)} L${ex - h * Math.cos(ang + 0.5)},${ey - h * Math.sin(ang + 0.5)} Z`,
