      const r = l + w, b = t + h;
      if (l < 2 || t < 2 || r > W - 2 || b > W - 2) return false;
      // nearest point of the box to the centre must be outside the circle
      const nx = Math.max(l, Math.min(c, r)), ny = Math.max(t, Math.min(c, b));
