    `$\\theta = ${view.thetaTex}${view.units === "radians" ? " = " + key.degrees + "^\\circ" : " = " + key.radTex}$`,
    same ? "" : `which lands in the same place as $${key.targetTex}$ (${key.degrees < 0 ? "negative angles turn clockwise" : "one full turn is $360^\\circ$"}).`,
  ].filter(Boolean).join(", ");
